__NUXT_JSONP__("/it/westwood", (function(a,b,c){return {data:[{details:{slug:a,pageTitle:"Westwood Campus | Mentor Language Institute",pageDescription:b,title:"Westwood Campus",image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fwestwood-campus.jpg",yt_link:"https:\u002F\u002Fwww.youtube.com\u002Fembed\u002F7f_pDJqW9Zg",subtitle:[b,"Westwood è particolarmente conosciuta per essere la sede di UCLA, una delle più prestigiose Università della California. Il campus è situato in Wilshire Blvd e Westwood Blvd.","È un quartiere entusiasmante e ricco di divertimento per studenti e lavoratori grazie alla presenza di moltissimi negozi,ristoranti e posti tranquilli in cui trascorrere la serata."],landmark:[{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fsanta-monica.jpg",title:"A 20 minuti di autobus da Santa Monica"},{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fbeverly-hills.jpg",title:"A 10 minuti di autobus da Beverly Hills"},{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Flos-angeles-skyline.jpg",title:"A 60 minuti di autobus da Downtown LA"}],gallery:{title:"Galleria Foto Westwood Campus",photos:[{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002F10880-building.jpg",title:"Si trova al primo piano dell'edificio. Non è necessario prendere l'ascensore per raggiungere la scuola."},{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Ffront-desk.jpg",title:"Reception"},{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fclassroom.jpg",title:"Aule"},{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fcomputer-room.jpg",title:"Aula Computer"},{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fstudent-lounge.jpg",title:"Sala studenti"},{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Ffree-space.jpg",title:"Spazio Libero"}]},location:{title:"Location",map_link:"https:\u002F\u002Fwww.google.com\u002Fmaps\u002Fembed?pb=!1m18!1m12!1m3!1d3305.4289041796537!2d-118.44512238478478!3d34.05851788060419!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x80c2bb7e2b42fadf%3A0xad96227841e11efb!2s10880+Wilshire+Blvd%2C+Los+Angeles%2C+CA+90024!5e0!3m2!1sen!2sus!4v1513884279258"},video:[{title:"1. Come arrivare al MLI Westwood Campus in autobus",youtube:"https:\u002F\u002Fwww.youtube.com\u002Fembed\u002FV2zydV7aWvA"},{title:"2. Come arrivare al MLI Westwood Campus in auto",space:"\u003Cbr\u002F\u003E",youtube:"https:\u002F\u002Fwww.youtube.com\u002Fembed\u002F5FXkkyV3DZg"}],environment:{title:"Ambiente",photos:[{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fucla.jpg",title:"Walking distance from UCLA"},{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fhammer-museum.jpg",title:"L' Hammer Museum, uno dei più famosi musei in Los Angeles, è proprio accanto al nostro Campus."},{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fwestwood-library.jpg",title:"C'è una Biblioteca alle spalle del campus"},{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fchevron-restaurant.jpg",title:"Ci sono molti ristoranti a prezzi accessibili"}]},accommodation:{title:"Alloggi",description:["Offriamo due opzioni per l'alloggio: Dormitorio e Programma Homestay"],types:[{desc:["＜Dormitori＞\u003Cbr \u002F\u003EDisponiamo di 40 camere nel dormitoro dello studente e da lì è possibile raggiungere la scuola a piedi o con l'autobus"],yt_link2:"https:\u002F\u002Fwww.youtube.com\u002Fembed\u002FV_eNdjw6Z1c"},{desc:["＜Programma Homestay＞"],other_desc:["Il Programma Homestay è il miglior modo per sapere di più degli usi e i costumi americani e avere la possibilità di praticare le proprie abilità comunicative anche in un ambiente familiare.","\u003Ca href=\"\u002Fit\u002Fstay\u002F\"\u003E\u003Ci class='bi bi-arrow-right'\u003E\u003C\u002Fi\u003E  Maggiori informazioni sugli alloggi\u003C\u002Fa\u003E"]}]},courses:{title:"Corsi",lists:["Programma ESL","TOEFL®","IELTS™","Conversazione","TOEIC®"]},message:{title:c,image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fwestwood-director.jpg",position:c,description:["Il Campus MLI di Westwood si trova in un'eccellente area nelle vicinanze di UCLA, ricca di una varietà di posti da visitare come musei, centri commerciali e teatri. I nostri corsi TOEFL hanno molto successo dal momento che molti degli studenti di MLI Westwood proseguono con gli studi universitari. Inoltre, i nostri prezzi sono davvero convenienti. C'è un'alta percentuale di studenti che si trasferiscono da altre scuole a MLI. Scarica la Brochure e scopri tutti i dettagli!"]},dir:"\u002Fwestwood",path:"\u002Fwestwood\u002Fit",extension:".json",createdAt:"2026-10-22T16:31:31.415Z",updatedAt:"2025-05-26T12:06:28.046Z"},lang:a}],fetch:{},mutations:void 0}}("it","Westwood è un'area vivace ed unica nel suo genere, situata nella parte occidentale di Los Angeles.","Il Direttore del Campus")));